class InvalidFileStructureError(Exception):
    """
    Raised when file structure seems to be different from the assumed one.
    """
    pass


class UnexpectedMessageFound(Exception):
    """
    Raised when unexpected message is found in pcap file.
    """
    pass


class ExpectedMessageNotFound(Exception):
    """
    Raised when expected message is not found in pcap file.
    """
    pass


class AttachMsgsFoundInPcap(Exception):
    """
    Raised when attach should not be
    possible and still there are attach msgs in PCAP
    """


class UnexpectedNumberOfAttachMsgs(Exception):
    """
    Raised when number of OK msgs in pcap after parallel call is
    different from expected
    """
    pass


class InvalidRan(Exception):
    """
    Raised when RAN type is invalid
    """
    pass
